func (q *Queries) Workspace(ctx context.Context, id string) (Workspace, error) {
	row := q.db.QueryRow(ctx, workspace, id)
	var i Workspace
	err := row.Scan(&i.ID, &i.Name, &i.CreatedAt)
	return i, err
}

const workspaceAdmin = `-- name: WorkspaceAdmin :one
SELECT u.id, u.email, u.seen_at FROM members m JOIN users u ON u.id = m.user_id
WHERE m.workspace_id = $1 AND m.role = 'admin'
`

func (q *Queries) WorkspaceAdmin(ctx context.Context, workspaceID string) (User, error) {
	row := q.db.QueryRow(ctx, workspaceAdmin, workspaceID)
	var i User
	err := row.Scan(&i.ID, &i.Email, &i.SeenAt)
	return i, err
}
